# django/contrib/auth/views.py:45-55  (django.contrib.auth.views.RedirectURLMixin.get_redirect_url)
class RedirectURLMixin:
    def get_redirect_url(self):
        """Return the user-originating redirect URL if it's safe."""
        redirect_to = self.request.POST.get(
            self.redirect_field_name, self.request.GET.get(self.redirect_field_name)
        )
        url_is_safe = url_has_allowed_host_and_scheme(
            url=redirect_to,
            allowed_hosts=self.get_success_url_allowed_hosts(),
            require_https=self.request.is_secure(),
        )
        return redirect_to if url_is_safe else ""

# tests/utils_tests/test_http.py:235-249  (tests.utils_tests.test_http.URLHasAllowedHostAndSchemeTests.test_no_allowed_hosts)
class URLHasAllowedHostAndSchemeTests(unittest.TestCase):
    def test_no_allowed_hosts(self):
        # A path without host is allowed.
        self.assertIs(
            url_has_allowed_host_and_scheme(
                "/confirm/me@example.com", allowed_hosts=None
            ),
            True,
        )
        # Basic auth without host is not allowed.
        self.assertIs(
            url_has_allowed_host_and_scheme(
                r"http://testserver\@example.com", allowed_hosts=None
            ),
            False,
        )

